WITH payload AS (
  SELECT * FROM jsonb_to_recordset('[{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"Una persona está sana y recibe una vacuna. ¿Qué se intenta evitar?","OPCION_A":"Reducir secuelas y recuperar funciones; es prevención terciaria.","OPCION_B":"A la prevención secundaria.","OPCION_C":"Que la enfermedad aparezca; por eso es prevención primaria.","OPCION_D":"Prevención secundaria.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Que la enfermedad aparezca; por eso es prevención primaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"¿En qué momento actúa la prevención primaria?","OPCION_A":"Prevención terciaria, porque intenta reducir secuelas de una enfermedad establecida.","OPCION_B":"Antes de que aparezca la enfermedad, reduciendo la exposición a sus factores de riesgo.","OPCION_C":"Prevención primaria, porque actúa antes de que se produzca la enfermedad.","OPCION_D":"Encontrar la enfermedad a tiempo para tratarla antes de que progrese: prevención secundaria.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Antes de que aparezca la enfermedad, reduciendo la exposición a sus factores de riesgo.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"medio","PREGUNTA":"Si una comunidad mejora el acceso a agua segura para evitar infecciones, ¿qué prevención realiza?","OPCION_A":"Prevención primaria.","OPCION_B":"Prevención terciaria, porque intenta reducir secuelas de una enfermedad establecida.","OPCION_C":"Prevención primaria, porque actúa antes de que se produzca la enfermedad.","OPCION_D":"Antes de que aparezca la enfermedad, reduciendo la exposición a sus factores de riesgo.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Prevención primaria, porque actúa antes de que se produzca la enfermedad.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"¿Qué busca un programa de detección temprana del cáncer cervicouterino?","OPCION_A":"Disminuir sus consecuencias y favorecer la recuperación funcional; corresponde a prevención terciaria.","OPCION_B":"Antes de que aparezca la enfermedad, reduciendo la exposición a sus factores de riesgo.","OPCION_C":"Encontrar la enfermedad a tiempo para tratarla antes de que progrese: prevención secundaria.","OPCION_D":"Prevención terciaria, porque intenta reducir secuelas de una enfermedad establecida.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Encontrar la enfermedad a tiempo para tratarla antes de que progrese: prevención secundaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué un tamizaje no se considera prevención primaria?","OPCION_A":"Porque busca una enfermedad que ya podría estar presente, aunque todavía no cause síntomas.","OPCION_B":"Porque protege antes de que la persona contraiga la enfermedad que se quiere evitar.","OPCION_C":"Si la enfermedad aún no ha aparecido, es primaria; si se busca detectarla temprano, es secundaria.","OPCION_D":"Antes de que aparezca la enfermedad, reduciendo la exposición a sus factores de riesgo.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Porque busca una enfermedad que ya podría estar presente, aunque todavía no cause síntomas.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"Una prueba de VIH permite iniciar tratamiento oportuno. ¿Qué nivel de prevención representa la detección?","OPCION_A":"Prevención secundaria.","OPCION_B":"Prevención secundaria: busca detección y tratamiento oportunos.","OPCION_C":"A la prevención secundaria.","OPCION_D":"Prevención primaria.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Prevención secundaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"Una persona ya tuvo un infarto y empieza rehabilitación. ¿Cuál es el objetivo preventivo?","OPCION_A":"Prevención terciaria, porque intenta reducir secuelas de una enfermedad establecida.","OPCION_B":"A la prevención secundaria.","OPCION_C":"Reducir secuelas y recuperar funciones; es prevención terciaria.","OPCION_D":"Prevención secundaria: busca detección y tratamiento oportunos.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Reducir secuelas y recuperar funciones; es prevención terciaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"¿En qué se diferencia la prevención terciaria de la secundaria?","OPCION_A":"La promoción fortalece condiciones y capacidades para el bienestar; la prevención se centra en riesgos y enfermedades.","OPCION_B":"La prevención cuaternaria, que busca evitar daños por exceso de intervención médica.","OPCION_C":"La secundaria busca detectar y tratar temprano; la terciaria limita complicaciones de una enfermedad ya establecida.","OPCION_D":"El sobrediagnóstico y el sobretratamiento.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La secundaria busca detectar y tratar temprano; la terciaria limita complicaciones de una enfermedad ya establecida.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"¿Qué pretende la reinserción social tras una enfermedad mental?","OPCION_A":"Encontrar la enfermedad a tiempo para tratarla antes de que progrese: prevención secundaria.","OPCION_B":"Disminuir sus consecuencias y favorecer la recuperación funcional; corresponde a prevención terciaria.","OPCION_C":"Antes de que aparezca la enfermedad, reduciendo la exposición a sus factores de riesgo.","OPCION_D":"Prevención terciaria, porque intenta reducir secuelas de una enfermedad establecida.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Disminuir sus consecuencias y favorecer la recuperación funcional; corresponde a prevención terciaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"Un examen sin indicación puede iniciar tratamientos innecesarios. ¿Qué nivel de prevención pide detenerse?","OPCION_A":"La secundaria busca detectar y tratar temprano; la terciaria limita complicaciones de una enfermedad ya establecida.","OPCION_B":"La prevención cuaternaria, que busca evitar daños por exceso de intervención médica.","OPCION_C":"La promoción fortalece condiciones y capacidades para el bienestar; la prevención se centra en riesgos y enfermedades.","OPCION_D":"El sobrediagnóstico y el sobretratamiento.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La prevención cuaternaria, que busca evitar daños por exceso de intervención médica.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"¿Qué dos riesgos intenta reducir la prevención cuaternaria?","OPCION_A":"La promoción fortalece condiciones y capacidades para el bienestar; la prevención se centra en riesgos y enfermedades.","OPCION_B":"La prevención cuaternaria, que busca evitar daños por exceso de intervención médica.","OPCION_C":"El sobrediagnóstico y el sobretratamiento.","OPCION_D":"La secundaria busca detectar y tratar temprano; la terciaria limita complicaciones de una enfermedad ya establecida.","RESPUESTA_CORRECTA":"C","EXPLICACION":"El sobrediagnóstico y el sobretratamiento.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"¿La prevención se limita a dar medicamentos?","OPCION_A":"Prevención terciaria, porque intenta reducir secuelas de una enfermedad establecida.","OPCION_B":"Si la enfermedad aún no ha aparecido, es primaria; si se busca detectarla temprano, es secundaria.","OPCION_C":"Porque busca una enfermedad que ya podría estar presente, aunque todavía no cause síntomas.","OPCION_D":"No. También incluye reducir riesgos, detectar temprano y evitar secuelas o intervenciones dañinas.","RESPUESTA_CORRECTA":"D","EXPLICACION":"No. También incluye reducir riesgos, detectar temprano y evitar secuelas o intervenciones dañinas.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"¿Qué pregunta te ayuda a distinguir prevención primaria de secundaria?","OPCION_A":"Si la enfermedad aún no ha aparecido, es primaria; si se busca detectarla temprano, es secundaria.","OPCION_B":"Porque busca una enfermedad que ya podría estar presente, aunque todavía no cause síntomas.","OPCION_C":"Porque protege antes de que la persona contraiga la enfermedad que se quiere evitar.","OPCION_D":"La promoción fortalece condiciones y capacidades para el bienestar; la prevención se centra en riesgos y enfermedades.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Si la enfermedad aún no ha aparecido, es primaria; si se busca detectarla temprano, es secundaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"Una citología cervical busca identificar lesiones tempranas. ¿A qué nivel corresponde?","OPCION_A":"Prevención secundaria.","OPCION_B":"A la prevención secundaria.","OPCION_C":"Prevención terciaria.","OPCION_D":"Reducir secuelas y recuperar funciones; es prevención terciaria.","RESPUESTA_CORRECTA":"B","EXPLICACION":"A la prevención secundaria.","F