iene agua segura y otro no. ¿Qué medida apunta a la equidad?","OPCION_A":"Actuar sobre diferencias evitables e injustas para que todas las personas tengan oportunidades de bienestar.","OPCION_B":"Requiere prevención, hábitos saludables y trabajo con los factores de riesgo de la comunidad.","OPCION_C":"Disminuye el peso relativo de infecciones y aumentan las enfermedades crónicas no transmisibles.","OPCION_D":"Actuar sobre esa diferencia para que ambos tengan una oportunidad similar de mantenerse sanos.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Actuar sobre esa diferencia para que ambos tengan una oportunidad similar de mantenerse sanos.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"¿Qué sucede con las enfermedades predominantes durante la transición epidemiológica descrita en el PDF?","OPCION_A":"Actuar sobre diferencias evitables e injustas para que todas las personas tengan oportunidades de bienestar.","OPCION_B":"Disminuye el peso relativo de infecciones y aumentan las enfermedades crónicas no transmisibles.","OPCION_C":"Políticas, distribución de la riqueza y educación.","OPCION_D":"Requiere prevención, hábitos saludables y trabajo con los factores de riesgo de la comunidad.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Disminuye el peso relativo de infecciones y aumentan las enfermedades crónicas no transmisibles.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"medio","PREGUNTA":"Si la población vive más años y cambian las principales causas de muerte, ¿qué dos transiciones se relacionan?","OPCION_A":"La física, la mental y la social.","OPCION_B":"Los determinantes sociales y ambientales de la salud.","OPCION_C":"La demográfica y la epidemiológica.","OPCION_D":"La interacción de factores biológicos, psicológicos y sociales.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La demográfica y la epidemiológica.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué el aumento de enfermedades crónicas exige algo más que atención hospitalaria?","OPCION_A":"Disminuye el peso relativo de infecciones y aumentan las enfermedades crónicas no transmisibles.","OPCION_B":"Requiere prevención, hábitos saludables y trabajo con los factores de riesgo de la comunidad.","OPCION_C":"Actuar sobre esa diferencia para que ambos tengan una oportunidad similar de mantenerse sanos.","OPCION_D":"Principalmente como ausencia de enfermedad, con énfasis en diagnóstico y tratamiento.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Requiere prevención, hábitos saludables y trabajo con los factores de riesgo de la comunidad.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"¿Qué ejemplos da el material de condiciones de vida diarias que afectan la salud?","OPCION_A":"Políticas, distribución de la riqueza y educación.","OPCION_B":"Entre otros, edad, sexo y herencia genética.","OPCION_C":"Actuar sobre diferencias evitables e injustas para que todas las personas tengan oportunidades de bienestar.","OPCION_D":"Vivienda, alimentación y acceso a servicios.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Vivienda, alimentación y acceso a servicios.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"¿Qué ejemplos da de factores estructurales de la salud?","OPCION_A":"Entre otros, edad, sexo y herencia genética.","OPCION_B":"Vivienda, alimentación y acceso a servicios.","OPCION_C":"Políticas, distribución de la riqueza y educación.","OPCION_D":"Actuar sobre diferencias evitables e injustas para que todas las personas tengan oportunidades de bienestar.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Políticas, distribución de la riqueza y educación.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"}]'::jsonb) AS p("MATERIA" text, "TEMA" text, "DIFICULTAD" text, "PREGUNTA" text, "OPCION_A" text, "OPCION_B" text, "OPCION_C" text, "OPCION_D" text, "RESPUESTA_CORRECTA" text, "EXPLICACION" text, "FUENTE" text, "PAGINAS_PDF" text)
), missing AS (
  SELECT p.* FROM payload p
  WHERE NOT EXISTS (
    SELECT 1 FROM public.banco_preguntas b
    WHERE b."MATERIA" = p."MATERIA" AND lower(b."PREGUNTA") = lower(p."PREGUNTA")
  )
), numbered AS (
  SELECT (SELECT coalesce(max(id), 0) FROM public.banco_preguntas) + row_number() OVER (ORDER BY "MATERIA", "TEMA", "PREGUNTA") AS id, m.*
  FROM missing m
)
INSERT INTO public.banco_preguntas (id, "MATERIA", "TEMA", "DIFICULTAD", "PREGUNTA", "OPCION_A", "OPCION_B", "OPCION_C", "OPCION_D", "RESPUESTA_CORRECTA", "EXPLICACION", "FUENTE", "PAGINAS_PDF")
SELECT n.id, n."MATERIA", n."TEMA", n."DIFICULTAD", n."PREGUNTA", n."OPCION_A", n."OPCION_B", n."OPCION_C", n."OPCION_D", n."RESPUESTA_CORRECTA", n."EXPLICACION", n."FUENTE", n."PAGINAS_PDF" FROM numbered n;
COMMIT;

