WITH payload AS (
  SELECT * FROM jsonb_to_recordset('[{"MATERIA":"MORFOFUNCION","TEMA":"aparato respiratorio","DIFICULTAD":"facil","PREGUNTA":"En el enfisema, ¿qué cambio dificulta la espiración?","OPCION_A":"Las reacciones se invierten, se libera CO2 y difunde hacia los alvéolos.","OPCION_B":"La pérdida de elasticidad y el atrapamiento de aire en los pulmones.","OPCION_C":"El aire que entra o sale durante una respiración tranquila.","OPCION_D":"El aire que permanece en los pulmones incluso después de una espiración máxima.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La pérdida de elasticidad y el atrapamiento de aire en los pulmones.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"883–920"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato respiratorio","DIFICULTAD":"facil","PREGUNTA":"¿Qué le hace la bronquitis crónica a las vías respiratorias?","OPCION_A":"Concentración o presión de oxígeno anormalmente baja en la sangre.","OPCION_B":"Produce inflamación y secreciones que dificultan el flujo de aire.","OPCION_C":"Cambios de pH y de gases en la sangre y el líquido cefalorraquídeo.","OPCION_D":"Entra cloruro a cambio; se conoce como desplazamiento de cloruro.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Produce inflamación y secreciones que dificultan el flujo de aire.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"883–920"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato respiratorio","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué fumar aumenta el riesgo de daño respiratorio y cáncer pulmonar?","OPCION_A":"Porque está reforzada por anillos de cartílago hialino en forma de C.","OPCION_B":"Para que oxígeno y dióxido de carbono difundan a corta distancia.","OPCION_C":"Porque expone repetidamente el epitelio a irritantes y carcinógenos.","OPCION_D":"Porque el corazón ocupa parte del lado izquierdo del mediastino.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Porque expone repetidamente el epitelio a irritantes y carcinógenos.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"883–920"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato respiratorio","DIFICULTAD":"facil","PREGUNTA":"¿Qué dos tareas de todo el aparato respiratorio conectan pulmones y metabolismo?","OPCION_A":"Entregar oxígeno a los tejidos y retirar el dióxido de carbono que producen.","OPCION_B":"Cambios de pH y de gases en la sangre y el líquido cefalorraquídeo.","OPCION_C":"A temperatura constante, al aumentar el volumen de un gas disminuye su presión.","OPCION_D":"Concentración o presión de oxígeno anormalmente baja en la sangre.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Entregar oxígeno a los tejidos y retirar el dióxido de carbono que producen.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"883–920"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato respiratorio","DIFICULTAD":"facil","PREGUNTA":"¿Qué otro equilibrio corporal ayuda a regular la eliminación de CO2?","OPCION_A":"El grupo respiratorio ventral.","OPCION_B":"El equilibrio ácido-base o pH.","OPCION_C":"La anhidrasa carbónica.","OPCION_D":"Las hace vibrar y produce sonido.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El equilibrio ácido-base o pH.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"883–920"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"Al masticar una manzana, ¿qué tipo de digestión comienza primero?","OPCION_A":"La mecánica: los dientes fragmentan el alimento y aumentan su superficie.","OPCION_B":"El paladar blando o velo del paladar.","OPCION_C":"Una barrera de moco y bicarbonato que separa el epitelio del contenido ácido.","OPCION_D":"La fase intestinal, que reduce la secreción y la motilidad gástricas.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La mecánica: los dientes fragmentan el alimento y aumentan su superficie.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"Cuando una enzima rompe una molécula alimentaria, ¿qué tipo de digestión ocurre?","OPCION_A":"Digestión química, que descompone macromoléculas en unidades más pequeñas.","OPCION_B":"Dividir el glóbulo en gotas pequeñas para aumentar la superficie disponible.","OPCION_C":"Ayudan a aprovechar compuestos de la dieta y producen ciertas vitaminas.","OPCION_D":"Aumentan el área de contacto de la mucosa con el contenido intestinal.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Digestión química, que descompone macromoléculas en unidades más pequeñas.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué cinco etapas generales atraviesa el alimento desde que entra hasta que se elimina?","OPCION_A":"Sirven de paso a vasos sanguíneos, linfáticos y nervios.","OPCION_B":"Bicarbonato, que ayuda a neutralizar el ácido del quimo.","OPCION_C":"Manipular el alimento, formar el bolo y empujarlo para deglutir.","OPCION_D":"Ingestión, digestión, absorción, compactación y defecación.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Ingestión, digestión, absorción, compactación y defecación.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Los dientes pertenecen al tubo digestivo o son órganos accesorios?","OPCION_A":"Con músculo circular interno y longitudinal externo.","OPCION_B":"Sirven de paso a vasos sanguíneos, linfáticos y nervios.","OPCION_C":"Son órganos accesorios que ayudan a procesar el alimento.","OPCION_D":"Aumentan el área de contacto de la mucosa con el contenido intestinal.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Son órganos accesorios que ayudan a procesar el alimento.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Cuál es el recorrido del alimento desde la boca hasta el estómago?","OPCION_A":"Reflujo ácido que puede producir pirosis.","OPCION_B":"Boca, faringe, esófago y estómago.","OPCION_C":"Circulación enterohepática.","OPCION_D":"Ingestión, digestión, absorción, compactación y defecación.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Boca, faringe, esófago y estómago.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué capa de la pared digestiva toca directamente el alimento?","OPCION_A":"La submucosa.","OPCION_B":"La muscular externa.","OPCION_C":"La mucosa.","OPCION_D":"Los incisivos.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La mucosa.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué capa de la pared digestiva contiene vasos y un plexo nervioso bajo la mucosa?","OPCION_A":"La mucosa.","OPCION_B":"La muscular externa.","OPCION_C":"El plexo mientérico.","OPCION_D":"La submucosa.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La submucosa.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué capa de la pared digestiva genera buena parte de sus movimientos?","OPCION_A":"La muscular externa.","OPCION_B":"La submucosa.","OPCION_C":"La mucosa.","OPCION_D":"El plexo mientérico.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La muscular externa.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Cómo suele organizarse la muscular externa del tubo digestivo?","OPCION_A":"Secretan moco rico en bicarbonato que ayuda a neutralizarlo.","OPCION_B":"Con músculo circular interno y longitudinal externo.","OPCION_C":"Peristaltismo.","OPCION_D":"Son órganos accesorios que ayudan a procesar el alimento.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Con músculo circular interno y longitudinal externo.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué forma un engrosamiento de músculo circular en el tubo digestivo?","OPCION_A":"Los macrófagos hepáticos o células de Kupffer.","OPCION_B":"El colédoco, que conduce bilis hacia el duodeno.","OPCION_C":"Un esfínter que regula el paso del contenido.","OPCION_D":"Las células regenerativas o citoblastos.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Un esfínter que regula el paso del contenido.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué plexo del sistema nervioso entérico coordina especialmente la motilidad intestinal?","OPCION_A":"La submucosa.","OPCION_B":"El plexo mientérico.","OPCION_C":"La muscular externa.","OPCION_D":"El ácido clorhídrico.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El plexo mientérico.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué hacen los mesenterios además de sostener órganos abdominales?","OPCION_A":"Bicarbonato, que ayuda a neutralizar el ácido del quimo.","OPCION_B":"Sirven de paso a vasos sanguíneos, linfáticos y nervios.","OPCION_C":"Ingestión, digestión, absorción, compactación y defecación.","OPCION_D":"Colon ascendente, transverso, descendente y sigmoide.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Sirven de paso a vasos sanguíneos, linfáticos y nervios.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué epitelio protege al esófago del roce del bolo alimenticio?","OPCION_A":"Colon ascendente, transverso, descendente y sigmoide.","OPCION_B":"Agua y sales, con lo que ayuda a formar las heces.","OPCION_C":"Epitelio pavimentoso estratificado no queratinizado.","OPCION_D":"Sirven de paso a vasos sanguíneos, linfáticos y nervios.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Epitelio pavimentoso estratificado no queratinizado.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué estructura dura separa la boca de la cavidad nasal?","OPCION_A":"El paladar duro.","OPCION_B":"El paladar blando o velo del paladar.","OPCION_C":"La vitamina K.","OPCION_D":"Los incisivos.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El paladar duro.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué movimientos permite la lengua durante la alimentación?","OPCION_A":"Estimula la secreción y favorece la función digestiva del estómago.","OPCION_B":"Manipular el alimento, formar el bolo y empujarlo para deglutir.","OPCION_C":"Ingestión, digestión, absorción, compactación y defecación.","OPCION_D":"Sirven de paso a vasos sanguíneos, linfáticos y nervios.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Manipular el alimento, formar el bolo y empujarlo para deglutir.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué piezas dentales cortan principalmente el alimento?","OPCION_A":"Los premolares y molares.","OPCION_B":"Los caninos.","OPCION_C":"La mucosa.","OPCION_D":"Los incisivos.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Los incisivos.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué piezas dentales son especialmente útiles para desgarrar?","OPCION_A":"Los incisivos.","OPCION_B":"Los premolares y molares.","OPCION_C":"La insulina.","OPCION_D":"Los caninos.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Los caninos.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué piezas dentales muelen y trituran el alimento?","OPCION_A":"Los incisivos.","OPCION_B":"Los caninos.","OPCION_C":"Los premolares y molares.","OPCION_D":"El ligamento periodontal.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Los premolares y molares.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Cómo se llama la parte del diente visible por encima de la encía?","OPCION_A":"La corona.","OPCION_B":"El ciego.","OPCION_C":"La dentina.","OPCION_D":"El esmalte.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La corona.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué tejido duro recubre la corona del diente?","OPCION_A":"La dentina.","OPCION_B":"La insulina.","OPCION_C":"El glucagón.","OPCION_D":"El esmalte.","RESPUESTA_CORRECTA":"D","EXPLICACION":"El esmalte.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué tejido forma la mayor parte del diente debajo del esmalte?","OPCION_A":"La dentina.","OPCION_B":"El esmalte.","OPCION_C":"Los caninos.","OPCION_D":"Las micelas.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La dentina.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué une la raíz del diente con el hueso que la rodea?","OPCION_A":"Los premolares y molares.","OPCION_B":"Las células principales.","OPCION_C":"El ligamento periodontal.","OPCION_D":"Los ácinos pancreáticos.","RESPUESTA_CORRECTA":"C","EXPLICACION":"El ligamento periodontal.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Para qué sirve el moco de la saliva al formar el bolo?","OPCION_A":"Aumentan el área de contacto de la mucosa con el contenido intestinal.","OPCION_B":"Estimula la secreción y favorece la función digestiva del estómago.","OPCION_C":"Une y lubrica las partículas de alimento para facilitar la deglución.","OPCION_D":"Epitelio pavimentoso estratificado no queratinizado.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Une y lubrica las partículas de alimento para facilitar la deglución.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué enzima de la saliva empieza a digerir el almidón?","OPCION_A":"La amilasa pancreática.","OPCION_B":"La lipasa pancreática.","OPCION_C":"La muscular externa.","OPCION_D":"La amilasa salival.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La amilasa salival.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué tres pares de glándulas salivales grandes debes localizar?","OPCION_A":"Entre otras, la tripsina y la quimotripsina.","OPCION_B":"Agua y sales, con lo que ayuda a formar las heces.","OPCION_C":"Epitelio pavimentoso estratificado no queratinizado.","OPCION_D":"Parótidas, submandibulares y sublinguales.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Parótidas, submandibulares y sublinguales.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"medio","PREGUNTA":"Si sientes ardor por ácido que vuelve del estómago al esófago, ¿qué está ocurriendo?","OPCION_A":"Almidón, cuya digestión empieza con amilasas y continúa en el intestino delgado.","OPCION_B":"Boca, faringe, esófago y estómago.","OPCION_C":"Reflujo ácido que puede producir pirosis.","OPCION_D":"Parótidas, submandibulares y sublinguales.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Reflujo ácido que puede producir pirosis.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué esfínter ayuda a impedir que el contenido del estómago suba al esófago?","OPCION_A":"El ácido clorhídrico.","OPCION_B":"El esfínter esofágico inferior.","OPCION_C":"Las placas o parches de Peyer.","OPCION_D":"Las células enteroendocrinas.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El esfínter esofágico inferior.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"Al tragar, ¿qué bloquea la entrada del alimento hacia la nariz?","OPCION_A":"El paladar blando o velo del paladar.","OPCION_B":"El paladar duro.","OPCION_C":"La epiglotis.","OPCION_D":"La mecánica: los dientes fragmentan el alimento y aumentan su superficie.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El paladar blando o velo del paladar.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"Al tragar, ¿qué ayuda a evitar que el bolo entre en la laringe?","OPCION_A":"El paladar blando o velo del paladar.","OPCION_B":"La epiglotis.","OPCION_C":"La histamina.","OPCION_D":"El glucagón.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La epiglotis.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"medio","PREGUNTA":"¿Puede el peristaltismo llevar alimento al estómago aunque una persona no esté erguida?","OPCION_A":"Sí. Las contracciones esofágicas impulsan el bolo sin depender solo de la gravedad.","OPCION_B":"Porque nuestras enzimas digestivas no pueden romper sus enlaces de la misma manera.","OPCION_C":"Porque eleva el pH duodenal hasta un rango más favorable para su actividad.","OPCION_D":"Para mezclar el quimo con las secreciones y exponerlo a la mucosa.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Sí. Las contracciones esofágicas impulsan el bolo sin depender solo de la gravedad.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"dificil","PREGUNTA":"¿Qué diferencia hay entre el epitelio del esófago y el del estómago?","OPCION_A":"Los ácidos biliares, que participan en la emulsificación y formación de micelas.","OPCION_B":"El esófago tiene epitelio estratificado protector; el estómago, epitelio cilíndrico secretor.","OPCION_C":"El interno es involuntario; el externo está bajo control voluntario.","OPCION_D":"Las proteínas, que rompe en fragmentos más pequeños.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El esófago tiene epitelio estratificado protector; el estómago, epitelio cilíndrico secretor.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Cuántas capas musculares principales tiene la pared del estómago?","OPCION_A":"Estimula la secreción y favorece la función digestiva del estómago.","OPCION_B":"Tres: oblicua interna, circular media y longitudinal externa.","OPCION_C":"Secretan moco rico en bicarbonato que ayuda a neutralizarlo.","OPCION_D":"Ingestión, digestión, absorción, compactación y defecación.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Tres: oblicua interna, circular media y longitudinal externa.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué células gástricas secretan pepsinógeno?","OPCION_A":"Las células parietales.","OPCION_B":"Las células principales.","OPCION_C":"Las células enteroendocrinas.","OPCION_D":"Las células regenerativas o citoblastos.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Las células principales.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Qué células gástricas secretan ácido clorhídrico y factor intrínseco?","OPCION_A":"Las células principales.","OPCION_B":"Las células enteroendocrinas.","OPCION_C":"Las células regenerativas o citoblastos.","OPCION_D":"Las células parietales.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Las células parietales.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"},{"MATERIA":"MORFOFUNCION","TEMA":"aparato digestivo","DIFICULTAD":"facil","PREGUNTA":"¿Cómo pasa el pepsinógeno a ser pepsina activa?","OPCION_A":"El ambiente ácido elimina parte de la molécula y la activa.","OPCION_B":"La fase cefálica, mediada en gran parte 