  SELECT * FROM jsonb_to_recordset('[{"MATERIA":"BIOLOGIA CELULAR","TEMA":"biologia celular del cancer","DIFICULTAD":"facil","PREGUNTA":"¿Qué es la angiogénesis en el crecimiento de un tumor?","OPCION_A":"El que regula proliferación, diferenciación y muerte celular programada.","OPCION_B":"La vía sanguínea, linfática o serosa, según el tipo de tumor.","OPCION_C":"La formación de nuevos vasos sanguíneos que aportan oxígeno y nutrientes al tumor.","OPCION_D":"La respuesta inmunitaria, incluida la acción de linfocitos y células NK.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La formación de nuevos vasos sanguíneos que aportan oxígeno y nutrientes al tumor.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"650–696"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"biologia celular del cancer","DIFICULTAD":"facil","PREGUNTA":"¿Qué significa que un cáncer haya hecho metástasis?","OPCION_A":"Que cambia el uso de nutrientes y energía para sostener su proliferación.","OPCION_B":"Continúa avanzando en el ciclo y multiplicándose pese a señales que deberían detenerla.","OPCION_C":"Que células tumorales se han diseminado y han formado lesiones en otro sitio del organismo.","OPCION_D":"La formación de nuevos vasos sanguíneos que aportan oxígeno y nutrientes al tumor.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Que células tumorales se han diseminado y han formado lesiones en otro sitio del organismo.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"650–696"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"biologia celular del cancer","DIFICULTAD":"facil","PREGUNTA":"¿Cómo contribuye la pérdida de función de un gen supresor tumoral?","OPCION_A":"Permite que sobrevivan células alteradas que normalmente serían eliminadas.","OPCION_B":"Puede proliferar de manera descontrolada, una característica central del cáncer.","OPCION_C":"Elimina un freno normal del crecimiento o de la supervivencia celular.","OPCION_D":"Continúa avanzando en el ciclo y multiplicándose pese a señales que deberían detenerla.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Elimina un freno normal del crecimiento o de la supervivencia celular.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"650–696"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"respuesta inmunitaria","DIFICULTAD":"facil","PREGUNTA":"¿Cuál responde primero de forma general ante muchos microorganismos: la inmunidad innata o la adaptativa?","OPCION_A":"El linfocito B, al convertirse en célula plasmática.","OPCION_B":"La inmunidad innata; actúa con rapidez y reconoce patrones generales.","OPCION_C":"Permite una respuesta más eficaz cuando el organismo vuelve a encontrar el mismo antígeno.","OPCION_D":"Activar una respuesta protectora y memoria inmunitaria frente al agente real.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La inmunidad innata; actúa con rapidez y reconoce patrones generales.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"697–737"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"respuesta inmunitaria","DIFICULTAD":"facil","PREGUNTA":"¿Qué ventaja aporta la memoria de la inmunidad adaptativa?","OPCION_A":"Activar una respuesta protectora y memoria inmunitaria frente al agente real.","OPCION_B":"El linfocito B, al convertirse en célula plasmática.","OPCION_C":"La inmunidad innata; actúa con rapidez y reconoce patrones generales.","OPCION_D":"Permite una respuesta más eficaz cuando el organismo vuelve a encontrar el mismo antígeno.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Permite una respuesta más eficaz cuando el organismo vuelve a encontrar el mismo antígeno.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"697–737"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"respuesta inmunitaria","DIFICULTAD":"facil","PREGUNTA":"¿Qué célula puede producir anticuerpos después de activarse y diferenciarse?","OPCION_A":"El linfocito B, al convertirse en célula plasmática.","OPCION_B":"La inmunidad innata; actúa con rapidez y reconoce patrones generales.","OPCION_C":"Activar una respuesta protectora y memoria inmunitaria frente al agente real.","OPCION_D":"Permite una respuesta más eficaz cuando el organismo vuelve a encontrar el mismo antígeno.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El linfocito B, al convertirse en célula plasmática.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"697–737"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"respuesta inmunitaria","DIFICULTAD":"facil","PREGUNTA":"¿Qué busca una vacuna al presentar antígenos sin causar la enfermedad?","OPCION_A":"Permite una respuesta más eficaz cuando el organismo vuelve a encontrar el mismo antígeno.","OPCION_B":"El linfocito B, al convertirse en célula plasmática.","OPCION_C":"Activar una respuesta protectora y memoria inmunitaria frente al agente real.","OPCION_D":"La inmunidad innata; actúa con rapidez y reconoce patrones generales.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Activar una respuesta protectora y memoria inmunitaria frente al agente real.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"697–737"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"celulas madre y aplicaciones terapeuticas","DIFICULTAD":"medio","PREGUNTA":"¿Qué dos capacidades definen a una célula madre?","OPCION_A":"Tipos celulares derivados de las tres capas embrionarias, pero no tejido placentario por sí solas.","OPCION_B":"Autorrenovarse durante mucho tiempo y diferenciarse hacia células especializadas.","OPCION_C":"Tejidos extraembrionarios, como los de la placenta.","OPCION_D":"Más restringido: genera varios tipos celulares relacionados con el tejido o linaje al que pertenece.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Autorrenovarse durante mucho tiempo y diferenciarse hacia células especializadas.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"738–771"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"celulas madre y aplicaciones terapeuticas","DIFICULTAD":"medio","PREGUNTA":"¿Qué puede formar una célula madre totipotente que una pluripotente no forma por 